    for (const [start, end] of [['2026-10-01T01:00:00Z', ''], ['bad', '2026-10-01T02:00:00Z'],
      ['2026-10-01T03:00:00Z', '2026-10-01T02:00:00Z'], ['2026-10-01T01:00:00Z', '2026-10-03T02:00:00Z']]) {
      fireEvent.change(screen.getByLabelText('开始时间（UTC）'), { target: { value: start } });
      fireEvent.change(screen.getByLabelText('结束时间（UTC）'), { target: { value: end } });
      await userEvent.setup().click(screen.getByRole('button', { name: '发送问题' })); expect(bodies).toHaveLength(0);
    }
    fireEvent.change(screen.getByLabelText('开始时间（UTC）'), { target: { value: '2026-10-01T09:00:00+08:00' } });
    fireEvent.change(screen.getByLabelText('结束时间（UTC）'), { target: { value: '2026-10-01T10:00:00+08:00' } });
    await userEvent.setup().click(screen.getByRole('button', { name: '发送问题' })); await complete();
    expect(bodies[0]).toMatchObject({ start: '2026-10-01T01:00:00.000Z', end: '2026-10-01T02:00:00.000Z' });
  });

  it('连续点击只提交一次，停止接收保留已接纳任务', async () => {
    let streamController!: ReadableStreamDefaultController<Uint8Array>;
    server.use(http.post(`${origin}/api/chat`, async ({ request }) => {
      requests.push(request); bodies.push(await request.json() as ChatInput);
      return new HttpResponse(new ReadableStream<Uint8Array>({ start(controller) { streamController = controller; controller.enqueue(new TextEncoder().encode(frame('task', receipt()))); } }),
        { headers: { 'Content-Type': 'text/event-stream' } });
    }));
    mount(); await screen.findByLabelText('问题');
    fireEvent.change(screen.getByLabelText('问题'), { target: { value: '等待回答' } });
    const button = screen.getByRole('button', { name: '发送问题' }); fireEvent.click(button); fireEvent.click(button);
    await screen.findByRole('link', { name: `查看任务 ${taskId}` });
    await userEvent.setup().click(screen.getByRole('button', { name: '停止接收' }));
    await screen.findByText(/回答连接已停止/);
    expect(bodies).toHaveLength(1);
    expect(requests.filter((request) => request.method !== 'GET').map((request) => new URL(request.url).pathname)).toEqual(['/api/chat']);
    try { streamController.close(); } catch { /* 流可能已被取消 */ }
  });

  it('回答文本安全展示，未核对的 Evidence 不生成链接', async () => {
    respond({ ...answer, answer: `<img src=x onerror=alert(1)>[Evidence:${nextId}][Evidence:${evidenceId}]` });
    const { container } = mount(); await send(); await complete();
    expect(container.querySelector('.chat-answer img')).toBeNull();
    expect(screen.queryByRole('link', { name: `查看证据 ${nextId}` })).not.toBeInTheDocument();
    expect(screen.getAllByRole('link', { name: `查看证据 ${evidenceId}` })).toHaveLength(2);
  });

  it('done 的任务身份不符时拒绝交付', async () => {
    server.use(http.post(`${origin}/api/chat`, () => new HttpResponse(frame('task', receipt()) + frame('done', { ...answer, task_id: nextId }),
      { headers: { 'Content-Type': 'text/event-stream' } })));
    mount(); await send(); await screen.findByText('回答暂未完成');
    expect(screen.queryByText('已关闭', { exact: true })).not.toBeInTheDocument();
  });

  it('无回答转人工不把片段当完成结论；新对话清除旧追问', async () => {
    respond({ ...answer, answer: null, evidence_ids: [], status: 'ESCALATED' });
    mount(); await send(); await screen.findByText('当前没有可交付回答，请查看任务详情与待处理事项。');
    expect(screen.queryByLabelText('基于上一轮追问')).not.toBeInTheDocument();
    await userEvent.setup().click(screen.getByRole('button', { name: '新对话' }));
    expect(screen.queryByText('第 1 轮 · payment-service')).not.toBeInTheDocument();
    expect(screen.getByText('从一个问题开始')).toBeInTheDocument();
  });

  it('无效任务链接不发出读取请求', async () => {
    mount('/chat?task=bad'); await screen.findByText('对话链接无效');
    expect(requests.some((request) => new URL(request.url).pathname.startsWith('/api/chat'))).toBe(false);
  });
});

import { Alert, Button, Card, Input, Tag } from 'antd';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useEffect, useRef, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import type { ChatAnswer, ChatInput, EventReceipt, TaskStatus } from '../api/generated/types.gen';
import { EvidenceDrawer, EvidenceLink, PageHeader, QueryState } from '../task-center/shared';
import { statusLabels } from '../task-center/labels';
import { ChatError, isUuid, readAnswer, streamAnswer } from './api';

type Turn = { input: ChatInput; receipt?: EventReceipt; answer?: ChatAnswer; text: string; ids: string[]; error?: Error };

function AnswerText({ text, ids }: { text: string; ids: string[] }) {
  return <div className="chat-answer">{text.split(/(\[Evidence:[0-9a-f-]{36}\])/gi).map((part, index) => {
    const id = part.match(/^\[Evidence:([0-9a-f-]{36})\]$/i)?.[1];
    return id && ids.includes(id) ? <EvidenceLink key={index} id={id} /> : <span key={index}>{part}</span>;
  })}</div>;
}

function Answer({ answer, text, ids, taskId }: { answer?: ChatAnswer; text: string; ids: string[]; taskId?: string }) {
  const references = answer?.evidence_ids ?? ids;
  return <>
    {taskId && <div className="chat-task"><Tag>Human 任务</Tag><Link to={`/tasks/${taskId}`}>查看任务 {taskId}</Link></div>}
    {answer && <div className="chat-result"><Tag color={answer.pending ? 'blue' : ['CLOSED', 'RESOLVED'].includes(answer.status) ? 'green' : 'gold'}>
      {Object.hasOwn(statusLabels, answer.status) ? statusLabels[answer.status as TaskStatus] : answer.status}</Tag>
      {answer.pending && <span>任务仍在处理，可手动读取已保存回答。</span>}
      {answer.policy_decision && <span>策略判定：{({ need_approval: '需要审批', allow: '允许', deny: '拒绝' } as Record<string, string>)[answer.policy_decision] ?? answer.policy_decision}</span>}
    </div>}
    <AnswerText text={answer ? answer.answer ?? '' : text} ids={references} />
    {answer && !answer.answer && <p>当前没有可交付回答，请查看任务详情与待处理事项。</p>}
    {references.length > 0 && <details className="chat-references"><summary>本轮证据（{references.length}）</summary>
      {references.map((id) => <EvidenceLink key={id} id={id} />)}</details>}
    {answer && <div className="chat-references">{[
      [answer.conclusion_evidence_id, '结论'], [answer.review_evidence_id, '反证复核'], [answer.plan_evidence_id, '动作计划'],
    ].map(([id, label]) => id && <span key={id}>{label}：<EvidenceLink id={id} /></span>)}</div>}
    {taskId && answer && ['WAITING_APPROVAL', 'NEED_HUMAN_JUDGMENT', 'WAITING_INFORMATION', 'ESCALATED', 'AUTOMATION_ABORTED'].includes(answer.status)
      && <Link className="task-control-link" to={`/approvals/${taskId}`}>查看人工处理</Link>}
  </>;
}

export function ChatPage() {
  const [params, setParams] = useSearchParams();
  const queryClient = useQueryClient();
  const selected = params.get('task');
  const [service, setService] = useState(() => params.get('service') ?? 'payment-service');
  const [start, setStart] = useState(() => params.get('start') ?? '');
  const [end, setEnd] = useState(() => params.get('end') ?? '');
  const [mode, setMode] = useState<NonNullable<ChatInput['mode']>>('question');
  const [message, setMessage] = useState('');
  const [follow, setFollow] = useState(true);
  const [turns, setTurns] = useState<Turn[]>([]);
  const [busy, setBusy] = useState(false);
  const [validation, setValidation] = useState('');
  const controller = useRef<AbortController | null>(null);
  const loaded = useQuery({ queryKey: ['chat-answer', selected],
    enabled: Boolean(selected && isUuid(selected) && !turns.some((turn) => turn.receipt?.task_id === selected)),
    queryFn: ({ signal }) => readAnswer(selected!, signal), refetchOnWindowFocus: false });
  useEffect(() => () => controller.current?.abort(), []);
  const last = turns.at(-1);
  const previous = last?.answer && !last.answer.pending && last.answer.answer ? last.answer.task_id
    : !last && loaded.data && !loaded.data.pending && loaded.data.answer ? loaded.data.task_id : undefined;
  const mayFollow = previous && (!last || last.input.service_name === service.trim());

  function update(id: string, values: Partial<Turn> | ((turn: Turn) => Partial<Turn>)) {
    setTurns((old) => old.map((turn) => turn.input.request_id === id ? { ...turn, ...(typeof values === 'function' ? values(turn) : values) } : turn));
  }
  async function send(input: ChatInput, retry = false) {
    if (controller.current) return;
    const current = new AbortController(); controller.current = current; setBusy(true); setValidation('');
    if (retry) update(input.request_id, { text: '', ids: [], error: undefined, answer: undefined });
    else setTurns((old) => [...old, { input, text: '', ids: [] }]);
    try {
      await streamAnswer(input, current.signal, {
        task: (receipt) => {
          update(input.request_id, { receipt });
          setParams((old) => { const next = new URLSearchParams(old); next.set('task', receipt.task_id);
            next.set('service', input.service_name); next.delete('evidence');
            for (const field of ['start', 'end'] as const) { const value = input[field];
              if (value) next.set(field, value); else next.delete(field); }
            return next; }, { replace: true });
          void queryClient.invalidateQueries({ queryKey: ['tasks'] });
        },
        evidence: (ids) => update(input.request_id, { ids }),
        delta: (text) => update(input.request_id, (turn) => ({ text: turn.text + text })),
        done: (answer) => {
          update(input.request_id, { answer }); queryClient.setQueryData(['chat-answer', answer.task_id], answer);
          void queryClient.invalidateQueries({ queryKey: ['tasks'] });
          void queryClient.invalidateQueries({ queryKey: ['dashboard'] });
          for (const key of ['task', 'task-evidence', 'task-history', 'task-tool-calls', 'interaction'])
            void queryClient.invalidateQueries({ queryKey: [key, answer.task_id] });
        },
      });
      setMessage('');
    } catch (error) {
      update(input.request_id, { error: current.signal.aborted ? new Error('回答连接已停止，已接纳任务继续处理。可读取已保存回答或按原内容重试。')
        : error instanceof Error ? error : new ChatError() });
    } finally {
      if (controller.current === current) { controller.current = null; setBusy(false); }
    }
  }

  function submit() {
    if (controller.current) return;
    const serviceName = service.trim();
    if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/.test(serviceName) || !message.trim() || message.trim().length > 4000) {
      setValidation('请填写有效服务标识和 1–4000 字的问题。'); return;
    }
    if (Boolean(start) !== Boolean(end) || (start && end && (![start, end].every((value) => /(Z|[+-]\d{2}:\d{2})$/i.test(value)
      && Number.isFinite(Date.parse(value))) || Date.parse(end) <= Date.parse(start) || Date.parse(end) - Date.parse(start) > 86400000))) {
      setValidation('UTC 时间窗须同时填写，带时区，结束晚于开始且最长 24 小时。'); return;
    }
    void send({ request_id: crypto.randomUUID(), service_name: serviceName, message: message.trim(), mode,
      previous_task_id: follow && mayFollow ? previous : null,
      start: start ? new Date(start).toISOString() : null, end: end ? new Date(end).toISOString() : null });
  }

  async function recover(turn: Turn) {
    if (!turn.receipt || controller.current) return;
    const current = new AbortController(); controller.current = current; setBusy(true);
    try { const answer = await readAnswer(turn.receipt.task_id, current.signal);
      update(turn.input.request_id, { answer, error: undefined }); }
    catch (error) { update(turn.input.request_id, { error: error instanceof Error ? error : new ChatError() }); }
    finally { if (controller.current === current) { controller.current = null; setBusy(false); } }
  }

  return <section>
    <PageHeader title="AI 对话" description="围绕服务调查问题、核对证据，并跟进统一任务的处理结果。">
      <Button disabled={busy} onClick={() => { setTurns([]); setMessage(''); setValidation('');
        setParams((old) => { const next = new URLSearchParams(old); next.delete('task'); next.delete('evidence'); return next; }); }}>新对话</Button>
    </PageHeader>
    <div className="chat-layout">
      <div className="chat-thread" aria-label="对话记录" aria-busy={busy}>
        {!turns.length && !selected && <Card><h2>从一个问题开始</h2><p>填写服务和问题，回答会逐段显示。引用的证据可直接打开，任务进展可在 AI 任务中心查看。</p></Card>}
        {!turns.length && selected && <>
          {!isUuid(selected) ? <Alert type="error" role="alert" title="对话链接无效" />
            : <><QueryState pending={loaded.isPending} error={loaded.error} retry={() => void loaded.refetch()} />
              {loaded.data && !loaded.isError && <Card title="已保存回答">
                <Answer answer={loaded.data} text="" ids={[]} taskId={selected} />
                <Button onClick={() => void loaded.refetch()} loading={loaded.isFetching}>读取已保存回答</Button>
              </Card>}</>}
        </>}
        {turns.map((turn, index) => <Card key={turn.input.request_id} title={`第 ${index + 1} 轮 · ${turn.input.service_name}`}>
          <div className="chat-question"><span>本人</span><p>{turn.input.message}</p></div>
          <div className="chat-assistant"><span>运维大脑</span>
            <Answer answer={turn.answer} text={turn.text} ids={turn.ids} taskId={turn.receipt?.task_id} />
            {busy && index === turns.length - 1 && <p role="status">{turn.text ? '正在接收回答…' : '正在调查并核验证据…'}</p>}
            {turn.error && <Alert type="error" role="alert" title="回答暂未完成" description={turn.error.message} />}
            {!busy && (turn.error || turn.answer?.pending) && <div className="control-buttons">
              {turn.receipt && <Button onClick={() => void recover(turn)}>读取已保存回答</Button>}
              {turn.error && !(turn.error instanceof ChatError && [404, 409, 422].includes(turn.error.status))
                && <Button onClick={() => void send(turn.input, true)}>按原内容重试</Button>}
            </div>}
          </div>
        </Card>)}
      </div>
      <Card className="chat-composer" title="发起问题">
        <form onSubmit={(event) => { event.preventDefault(); submit(); }}>
          <label className="catalog-field" htmlFor="chat-service">服务标识<Input id="chat-service" value={service} onChange={(event) => setService(event.target.value)} disabled={busy} maxLength={128} /></label>
          <div className="catalog-field"><label htmlFor="chat-mode">请求方式</label><select id="chat-mode" value={mode} disabled={busy}
            onChange={(event) => setMode(event.target.value as NonNullable<ChatInput['mode']>)}>
            <option value="question">只读问答</option><option value="task">发起处置任务</option></select></div>
          <p className="chat-mode-note">{mode === 'question' ? '只读调查与回答。' : '进入统一处置流程；需要审批的动作请到审批中心明确授权。'}</p>
          <div className="catalog-field"><label htmlFor="chat-message">问题</label><Input.TextArea id="chat-message" rows={5} maxLength={4000} showCount disabled={busy} value={message} onChange={(event) => setMessage(event.target.value)} /></div>
          <details className="chat-window"><summary>查询时间窗（可选）</summary>
            <label className="catalog-field" htmlFor="chat-start">开始时间（UTC）<Input id="chat-start" placeholder="2026-10-01T01:00:00Z" value={start} disabled={busy} onChange={(event) => setStart(event.target.value)} /></label>
            <label className="catalog-field" htmlFor="chat-end">结束时间（UTC）<Input id="chat-end" placeholder="2026-10-01T02:00:00Z" value={end} disabled={busy} onChange={(event) => setEnd(event.target.value)} /></label>
            <p>留空查询接纳时刻前一小时；最长 24 小时。</p>
          </details>
          {mayFollow && <label className="chat-follow"><input type="checkbox" checked={follow} disabled={busy} onChange={(event) => setFollow(event.target.checked)} />基于上一轮追问</label>}
          {validation && <Alert type="error" role="alert" title={validation} />}
          <div className="control-buttons"><Button type="primary" htmlType="submit" disabled={busy}>发送问题</Button>
            {busy && <Button onClick={() => controller.current?.abort()}>停止接收</Button>}</div>
        </form>
      </Card>
    </div>
    <EvidenceDrawer />
  </section>;
}

import { apiClient, csrfHeaders } from '../api/client';
import {
  servicesApiServicesGet, serviceApiServicesServiceNameGet, dependenciesApiServicesServiceNameDependenciesGet,
  runbooksApiRunbooksGet, runbookApiRunbooksRunbookIdGet, createRunbookApiRunbooksPost,
  updateRunbookApiRunbooksRunbookIdPut, deleteRunbookApiRunbooksRunbookIdDelete,
  knowledgeApiKnowledgeGet, knowledgeEntryApiKnowledgeEntryIdGet, createKnowledgeApiKnowledgePost,
  updateKnowledgeApiKnowledgeEntryIdPut, deleteKnowledgeApiKnowledgeEntryIdDelete,
} from '../api/generated/sdk.gen';
import type { KnowledgeInput, KnowledgeType, RunbookInput, RunbookMaturity } from '../api/generated/types.gen';
import { ReadError } from '../task-center/api';

export class CatalogError extends Error {
  constructor(public readonly status: number) {
    super(status === 409 ? '名称已存在或内容发生冲突，请核对后再保存。'
      : status === 422 ? '内容不符合要求，请检查必填项、条件、风险等级与有效期。'
      : status === 404 ? '记录已不存在，请返回列表核对。'
      : status === 403 ? '请求校验失败，请刷新页面后重试。'
      : status === 401 ? '会话已失效，请重新登录。'
      : '保存结果尚未确认。请先返回列表核对是否已保存，再决定是否重试。');
  }
}

async function read<T>(request: Promise<{ data?: T; response?: Response }>): Promise<T> {
  const result = await request;
  if (!result.response?.ok || result.data === undefined) throw new ReadError(result.response?.status ?? 0);
  return result.data;
}
async function write<T>(request: Promise<{ data?: T; response?: Response }>): Promise<T> {
  const result = await request;
  if (!result.response?.ok || result.data === undefined) throw new CatalogError(result.response?.status ?? 0);
  return result.data;
}
async function remove(request: Promise<{ response?: Response }>) {
  const result = await request;
  if (result.response?.status !== 204) throw new CatalogError(result.response?.status ?? 0);
}
export const services = (offset: number, signal: AbortSignal) => read(servicesApiServicesGet({
  client: apiClient, query: { limit: 20, offset }, signal,
}));
export const graph = (name: string, hops: number, direction: 'both' | 'upstream' | 'downstream', signal: AbortSignal) =>
  direction === 'both' ? read(serviceApiServicesServiceNameGet({ client: apiClient, path: { service_name: name }, query: { hops }, signal }))
    : read(dependenciesApiServicesServiceNameDependenciesGet({ client: apiClient, path: { service_name: name }, query: { hops, direction }, signal }));
export const runbooks = (offset: number, maturity: RunbookMaturity | undefined, signal: AbortSignal) =>
  read(runbooksApiRunbooksGet({ client: apiClient, query: { limit: 20, offset, maturity }, signal }));
export const knowledge = (offset: number, kind: KnowledgeType | undefined, signal: AbortSignal) =>
  read(knowledgeApiKnowledgeGet({ client: apiClient, query: { limit: 20, offset, kind }, signal }));
export const runbook = (id: string, signal: AbortSignal) => read(runbookApiRunbooksRunbookIdGet({ client: apiClient, path: { runbook_id: id }, signal }));
export const entry = (id: string, signal: AbortSignal) => read(knowledgeEntryApiKnowledgeEntryIdGet({ client: apiClient, path: { entry_id: id }, signal }));
export const saveRunbook = (body: RunbookInput, id?: string) => write(id
  ? updateRunbookApiRunbooksRunbookIdPut({ client: apiClient, path: { runbook_id: id }, body, headers: csrfHeaders() })
  : createRunbookApiRunbooksPost({ client: apiClient, body, headers: csrfHeaders() }));
export const saveKnowledge = (body: KnowledgeInput, id?: string) => write(id
  ? updateKnowledgeApiKnowledgeEntryIdPut({ client: apiClient, path: { entry_id: id }, body, headers: csrfHeaders() })
  : createKnowledgeApiKnowledgePost({ client: apiClient, body, headers: csrfHeaders() }));
export const deleteRunbook = (id: string) => remove(deleteRunbookApiRunbooksRunbookIdDelete({ client: apiClient, path: { runbook_id: id }, headers: csrfHeaders() }));
export const deleteKnowledge = (id: string) => remove(deleteKnowledgeApiKnowledgeEntryIdDelete({ client: apiClient, path: { entry_id: id }, headers: csrfHeaders() }));

import { cloneElement, useId, useRef, useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { Alert, Button } from 'antd';
import { Link } from 'react-router-dom';
import type { ReactElement } from 'react';
import type { DiagnosticStep, KnowledgeInput, KnowledgeType, KnowledgeView, RiskLevel, RunbookCondition, RunbookInput, RunbookView } from '../api/generated/types.gen';
import * as api from './api';
import { knowledgeLabels } from './labels';

function Field({ label, children }: { label: string; children: ReactElement<{ id?: string }> }) {
  const id = useId();
  return <div className="catalog-field"><label htmlFor={id}>{label}</label>{cloneElement(children, { id })}</div>;
}
export function RiskSelect({ value, onChange, label = '风险等级' }: { value: RiskLevel; onChange: (value: RiskLevel) => void; label?: string }) {
  return <Field label={label}><select value={value} onChange={(event) => onChange(event.target.value as RiskLevel)}>
    {['只读查询', '低风险动作', '有限变更', '生产重要变更', '高风险生产操作', '破坏性或不可逆'].map((text, level) => <option key={level} value={`L${level}`}>L{level} · {text}</option>)}
  </select></Field>;
}
function Conditions({ title, rows, onChange }: { title: string; rows: RunbookCondition[]; onChange: (rows: RunbookCondition[]) => void }) {
  return <fieldset><legend>{title}</legend>{rows.map((row, index) => <div className="catalog-row" key={index}>
    <Field label={`${title} ${index + 1} 字段`}><select value={row.field} onChange={(event) => onChange(rows.map((item, at) => at === index ? { ...item, field: event.target.value as RunbookCondition['field'] } : item))}>
      <option value="service_name">服务名称</option><option value="title">任务标题</option><option value="task_source">任务来源</option></select></Field>
    <Field label={`${title} ${index + 1} 匹配方式`}><select value={row.operator} onChange={(event) => onChange(rows.map((item, at) => at === index ? { ...item, operator: event.target.value as RunbookCondition['operator'] } : item))}>
      <option value="equals">等于</option><option value="contains">包含</option></select></Field>
    <Field label={`${title} ${index + 1} 值`}><input required maxLength={4000} value={row.value} onChange={(event) => onChange(rows.map((item, at) => at === index ? { ...item, value: event.target.value } : item))} /></Field>
    <Button onClick={() => onChange(rows.filter((_, at) => at !== index))} disabled={title === '适用条件' && rows.length === 1}>删除{title} {index + 1}</Button>
  </div>)}<Button disabled={rows.length >= 30} onClick={() => onChange([...rows, { field: 'service_name', operator: 'equals', value: '' }])}>添加{title}</Button></fieldset>;
}
function SaveState({ error, validation, path }: { error: Error | null; validation: string; path: string }) {
  return <>{(validation || error) && <Alert role="alert" type="error" title="保存未完成" description={validation || error?.message} />}
    {error && <Link to={path}>返回列表核对保存结果</Link>}</>;
}

export function KnowledgeForm({ entry, saved, cancel }: { entry?: KnowledgeView; saved: (id: string) => Promise<void>; cancel: () => void }) {
  const [kind, setKind] = useState<KnowledgeType>(entry?.kind ?? 'business_rule');
  const [content, setContent] = useState(entry?.content ?? '');
  const [source, setSource] = useState(entry?.source ?? '');
  const [start, setStart] = useState(() => (entry?.valid_from ?? new Date().toISOString()).replace(/Z$/, ''));
  const [end, setEnd] = useState(entry?.expires_at?.replace(/Z$/, '') ?? '');
  const [validation, setValidation] = useState('');
  const lock = useRef(false);
  const mutation = useMutation({ mutationFn: (body: KnowledgeInput) => api.saveKnowledge(body, entry?.id), onSuccess: async (result) => saved(result.id) });
  async function submit() {
    if (lock.current) return;
    if (!content.trim() || !source.trim()) { setValidation('知识内容与来源不可为空白。'); return; }
    const from = new Date(start + 'Z'), until = end ? new Date(end + 'Z') : null;
    if (!Number.isFinite(from.getTime()) || (until && (!Number.isFinite(until.getTime()) || until <= from))) { setValidation('有效期结束必须晚于开始，时间使用 UTC。'); return; }
    setValidation(''); lock.current = true;
    try { await mutation.mutateAsync({ kind, content, source, valid_from: from.toISOString(), expires_at: until?.toISOString() ?? null }); } catch { /* 由 mutation 呈现错误，保留原输入。 */ } finally { lock.current = false; }
  }
  return <form className="catalog-form" onSubmit={(event) => { event.preventDefault(); void submit(); }}>
    <Field label="知识类型"><select value={kind} onChange={(event) => setKind(event.target.value as KnowledgeType)}>{Object.entries(knowledgeLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></Field>
    <Field label="知识内容"><textarea rows={8} required maxLength={20000} value={content} onChange={(event) => setContent(event.target.value)} /></Field>
    <Field label="知识来源"><input required maxLength={512} value={source} onChange={(event) => setSource(event.target.value)} placeholder="业务约定、文档或经验来源" /></Field>
    <div className="catalog-row"><Field label="生效时间（UTC）"><input type="datetime-local" step="0.001" required value={start} onChange={(event) => setStart(event.target.value)} /></Field>
      <Field label="失效时间（UTC，可留空）"><input type="datetime-local" step="0.001" value={end} onChange={(event) => setEnd(event.target.value)} /></Field></div>
    <SaveState error={mutation.error} validation={validation} path="/knowledge" />
    <div className="control-buttons"><Button htmlType="submit" type="primary" loading={mutation.isPending}>保存知识</Button><Button aria-label="取消" disabled={mutation.isPending} onClick={cancel}>取消</Button></div>
  </form>;
}

type DiagnosticForm = Omit<DiagnosticStep, 'parameters'> & { parameters_text: string };
export function RunbookForm({ entry, saved, cancel }: { entry?: RunbookView; saved: (id: string) => Promise<void>; cancel: () => void }) {
  const [content, setContent] = useState<RunbookInput>(() => entry ? {
    name: entry.name, description: entry.description, source: entry.source,
    applicability_conditions: entry.applicability_conditions, exclusion_conditions: entry.exclusion_conditions,
    diagnostic_steps: entry.diagnostic_steps, handling_steps: entry.handling_steps, risk_level: entry.risk_level,
    rollback_plan: entry.rollback_plan, verification_steps: entry.verification_steps,
  } : { name: '', description: '', source: '', applicability_conditions: [{ field: 'service_name', operator: 'equals', value: '' }], exclusion_conditions: [],
    diagnostic_steps: [], handling_steps: [{ description: '', risk_level: 'L3' }], risk_level: 'L3', rollback_plan: '', verification_steps: [] });
  const [diagnostics, setDiagnostics] = useState<DiagnosticForm[]>(() => entry?.diagnostic_steps.map((row) => ({ ...row, parameters_text: JSON.stringify(row.parameters, null, 2) }))
    ?? [{ description: '', tool_name: '', risk_level: 'L0', parameters_text: '{}' }]);
  const [verification, setVerification] = useState(entry?.verification_steps.join('\n') ?? '');
  const [validation, setValidation] = useState('');
  const lock = useRef(false);
  const mutation = useMutation({ mutationFn: (body: RunbookInput) => api.saveRunbook(body, entry?.id), onSuccess: async (result) => saved(result.id) });
  const change = <K extends keyof RunbookInput>(key: K, value: RunbookInput[K]) => setContent((previous) => ({ ...previous, [key]: value }));
  async function submit() {
    if (lock.current) return;
    try {
      const steps = diagnostics.map(({ parameters_text, ...step }) => {
        const parameters: unknown = JSON.parse(parameters_text);
        if (!parameters || typeof parameters !== 'object' || Array.isArray(parameters)) throw new Error('诊断参数必须是 JSON 对象。');
        return { ...step, parameters: parameters as DiagnosticStep['parameters'] };
      });
      const checks = verification.split('\n').map((line) => line.trim()).filter(Boolean);
      if (!checks.length || checks.length > 30 || checks.some((line) => line.length > 4000)) throw new Error('验证方式需要 1–30 条，每条最多 4000 字，每行一条。');
      if (content.handling_steps.some((step) => step.risk_level > content.risk_level)) throw new Error('总体风险等级不能低于任何处理步骤。');
      if ([content.description, content.source, content.rollback_plan, ...content.handling_steps.map((step) => step.description), ...steps.map((step) => step.description),
        ...content.applicability_conditions.map((row) => row.value), ...content.exclusion_conditions.map((row) => row.value)].some((value) => !value.trim())) throw new Error('必填内容与条件不可为空白。');
      setValidation(''); lock.current = true;
      try { await mutation.mutateAsync({ ...content, diagnostic_steps: steps, verification_steps: checks }); } catch { /* 保留输入，不自动重试。 */ } finally { lock.current = false; }
    } catch (error) { setValidation(error instanceof SyntaxError ? '诊断参数不是有效的 JSON 对象，请检查语法。' : (error as Error).message); }
  }
  return <form className="catalog-form" onSubmit={(event) => { event.preventDefault(); void submit(); }}>
    {entry && <Alert role="note" type="info" title="修改内容后将增加版本，并退回草稿等待审核。" />}
    <Field label="手册标识"><input required pattern="[a-z][a-z0-9_-]{0,127}" maxLength={128} value={content.name} onChange={(event) => change('name', event.target.value)} placeholder="例如 payment-connection-check" /></Field>
    <Field label="手册说明"><textarea rows={3} required maxLength={4000} value={content.description} onChange={(event) => change('description', event.target.value)} /></Field>
    <Field label="手册来源"><input required maxLength={4000} value={content.source} onChange={(event) => change('source', event.target.value)} /></Field>
    <Conditions title="适用条件" rows={content.applicability_conditions} onChange={(rows) => change('applicability_conditions', rows)} />
    <Conditions title="排除条件" rows={content.exclusion_conditions} onChange={(rows) => change('exclusion_conditions', rows)} />
    <fieldset><legend>诊断步骤（只读 L0）</legend>{diagnostics.map((row, index) => <div className="catalog-step" key={index}>
      <Field label={`诊断 ${index + 1} 说明`}><input required maxLength={4000} value={row.description} onChange={(event) => setDiagnostics(diagnostics.map((item, at) => at === index ? { ...item, description: event.target.value } : item))} /></Field>
      <Field label={`诊断 ${index + 1} Tool 名称`}><input required pattern="[a-z][a-z0-9_]{0,127}" value={row.tool_name} onChange={(event) => setDiagnostics(diagnostics.map((item, at) => at === index ? { ...item, tool_name: event.target.value } : item))} /></Field>
      <Field label={`诊断 ${index + 1} 参数（JSON 对象）`}><textarea rows={4} required value={row.parameters_text} onChange={(event) => setDiagnostics(diagnostics.map((item, at) => at === index ? { ...item, parameters_text: event.target.value } : item))} /></Field>
      <Button disabled={diagnostics.length === 1} onClick={() => setDiagnostics(diagnostics.filter((_, at) => at !== index))}>删除诊断 {index + 1}</Button>
    </div>)}<Button disabled={diagnostics.length >= 30} onClick={() => setDiagnostics([...diagnostics, { description: '', tool_name: '', parameters_text: '{}', risk_level: 'L0' }])}>添加诊断步骤</Button></fieldset>
    <fieldset><legend>处理步骤</legend>{content.handling_steps.map((row, index) => <div className="catalog-step" key={index}>
      <Field label={`处理 ${index + 1} 说明`}><textarea rows={2} required maxLength={4000} value={row.description} onChange={(event) => change('handling_steps', content.handling_steps.map((item, at) => at === index ? { ...item, description: event.target.value } : item))} /></Field>
      <RiskSelect label={`处理 ${index + 1} 风险`} value={row.risk_level} onChange={(value) => change('handling_steps', content.handling_steps.map((item, at) => at === index ? { ...item, risk_level: value } : item))} />
      <Button disabled={content.handling_steps.length === 1} onClick={() => change('handling_steps', content.handling_steps.filter((_, at) => at !== index))}>删除处理 {index + 1}</Button>
    </div>)}<Button disabled={content.handling_steps.length >= 30} onClick={() => change('handling_steps', [...content.handling_steps, { description: '', risk_level: content.risk_level }])}>添加处理步骤</Button></fieldset>
    <RiskSelect value={content.risk_level} onChange={(value) => change('risk_level', value)} />
    <Field label="回滚方案"><textarea rows={3} required maxLength={4000} value={content.rollback_plan} onChange={(event) => change('rollback_plan', event.target.value)} /></Field>
    <Field label="验证方式（每行一条）"><textarea rows={4} required value={verification} onChange={(event) => setVerification(event.target.value)} /></Field>
    <SaveState error={mutation.error} validation={validation} path="/runbooks" />
    <div className="control-buttons"><Button htmlType="submit" type="primary" loading={mutation.isPending}>保存手册</Button><Button aria-label="取消" disabled={mutation.isPending} onClick={cancel}>取消</Button></div>
  </form>;
}

import { useId, useLayoutEffect, useRef, useState } from 'react';
import { Card, Tooltip } from 'antd';
import type { EdgeView, GraphContext } from '../api/generated/types.gen';
import { Time } from '../task-center/shared';
import { age, nodeLabels } from './labels';

function EdgeFacts({ edge }: { edge: EdgeView }) {
  return <dl className="graph-facts"><div><dt>来源</dt><dd>{edge.source}</dd></div>
    <div><dt>置信度</dt><dd>{(edge.confidence * 100).toFixed(1)}%</dd></div>
    <div><dt>新鲜度</dt><dd>距上次观察 {age(edge.freshness_seconds)}（{edge.freshness_seconds} 秒）</dd></div>
    <div><dt>首次观察</dt><dd><Time value={edge.first_seen} /></dd></div>
    <div><dt>上次观察</dt><dd><Time value={edge.last_seen} /></dd></div></dl>;
}

export function ContextGraph({ graph }: { graph: GraphContext }) {
  const marker = useId().replace(/:/g, '');
  const viewport = useRef<HTMLDivElement>(null);
  const [selected, select] = useState<string | null>(null);
  const root = graph.nodes.find((node) => node.kind === 'service' && node.external_id === graph.service_name);
  const others = graph.nodes.filter((node) => node.id !== root?.id).sort((a, b) => a.kind.localeCompare(b.kind) || a.name.localeCompare(b.name));
  const width = 1100;
  const height = Math.max(260, Math.ceil(others.length / 2) * 76 + 80);
  const positions = new Map(graph.nodes.map((node) => [node.id, { x: width / 2, y: height / 2 }]));
  others.forEach((node, index) => positions.set(node.id, { x: index % 2 ? 900 : 200, y: 56 + Math.floor(index / 2) * 76 }));
  const names = new Map(graph.nodes.map((node) => [node.id, node.name]));
  const edge = graph.edges.find((item) => item.id === selected);
  const node = graph.nodes.find((item) => item.id === selected);
  useLayoutEffect(() => {
    const area = viewport.current;
    if (!area || !root) return;
    const center = () => { area.scrollLeft = Math.max(0, width / 2 - area.clientWidth / 2); area.scrollTop = Math.max(0, height / 2 - area.clientHeight / 2); };
    center(); const observer = new ResizeObserver(center); observer.observe(area);
    return () => observer.disconnect();
  }, [width, height, root]);
  return <div className="graph-layout">
    <Card title="服务关系图" extra={<span>{graph.nodes.length} 个节点 · {graph.edges.length} 条关系</span>}>
      <p className="control-description">箭头指向关系目标。悬停或聚焦关系查看来源与新鲜度；点击关系或节点查看详情。可在图内横向滚动。</p>
      <div ref={viewport} className="graph-scroll" tabIndex={0} aria-label="服务关系图滚动区域">
        <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} aria-label={`${graph.service_name} 上下文关系图`}>
          <defs><marker id={marker} markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#8796bc" /></marker></defs>
          {graph.edges.map((item, index) => {
            const from = positions.get(item.from_node_id), to = positions.get(item.to_node_id);
            if (!from || !to) return null;
            const label = `${names.get(item.from_node_id)} → ${names.get(item.to_node_id)} · ${item.relation} · ${item.source}`;
            const dx = to.x - from.x, dy = to.y - from.y, extent = Math.max(Math.abs(dx) / 122, Math.abs(dy) / 34) || 1;
            const x1 = from.x + dx / extent, y1 = from.y + dy / extent;
            const x2 = to.x - dx / extent, y2 = to.y - dy / extent;
            const curve = (index % 5 - 2) * 18;
            const path = from === to ? `M${from.x},${from.y - 28} c90,-85 90,85 0,56`
              : `M${x1},${y1} Q${(x1 + x2) / 2 + curve},${(y1 + y2) / 2 + curve} ${x2},${y2}`;
            return <Tooltip key={item.id} trigger={['hover', 'focus']} title={<><strong>{label}</strong><EdgeFacts edge={item} /></>}>
              <g role="button" tabIndex={0} aria-label={`关系 ${label}`} className="graph-edge"
                onClick={() => select(item.id)} onKeyDown={(event) => { if (['Enter', ' '].includes(event.key)) { event.preventDefault(); select(item.id); } }}>
                <path d={path} fill="none" stroke="transparent" strokeWidth="18" />
                <path d={path} fill="none" stroke={selected === item.id ? '#5668e8' : '#b4bfd8'} strokeWidth={selected === item.id ? 3 : 1.5} markerEnd={`url(#${marker})`} />
              </g>
            </Tooltip>;
          })}
          {graph.nodes.map((item) => {
            const point = positions.get(item.id)!;
            const isRoot = item.id === root?.id;
            return <g key={item.id} role="button" tabIndex={0} aria-label={`节点 ${item.name}`} className="graph-node"
              transform={`translate(${point.x},${point.y})`} onClick={() => select(item.id)}
              onKeyDown={(event) => { if (['Enter', ' '].includes(event.key)) { event.preventDefault(); select(item.id); } }}>
              <title>{item.name} · {nodeLabels[item.kind] ?? item.kind}</title>
              <rect x="-116" y="-28" width="232" height="56" rx="12" fill={isRoot ? '#5668e8' : '#f6f8fd'} stroke={selected === item.id ? '#5668e8' : '#d9e0ee'} />
              <text textAnchor="middle" y="-2" fill={isRoot ? '#fff' : '#243047'}>{item.name.length > 26 ? item.name.slice(0, 23) + '…' : item.name}</text>
              <text textAnchor="middle" y="17" fontSize="11" fill={isRoot ? '#dfe4ff' : '#8592ab'}>{nodeLabels[item.kind] ?? item.kind}</text>
            </g>;
          })}
        </svg>
      </div>
    </Card>
    <Card title={edge ? '关系详情' : node ? '节点详情' : '关系与节点'}>
      {edge ? <><p>{names.get(edge.from_node_id)} → {names.get(edge.to_node_id)}</p><p>{edge.relation}</p><EdgeFacts edge={edge} /><small>{edge.id}</small></>
        : node ? <dl className="record-meta"><div><dt>名称</dt><dd>{node.name}</dd></div><div><dt>类型</dt><dd>{nodeLabels[node.kind] ?? node.kind}</dd></div>
          <div><dt>源系统标识</dt><dd>{node.external_id}</dd></div><div><dt>节点 ID</dt><dd>{node.id}</dd></div></dl>
          : <p className="control-description">选择图中的关系或节点，或从下方关系清单选择。</p>}
    </Card>
    <Card title="关系清单" className="graph-relations"><ul>{graph.edges.map((item) => <li key={item.id}>
      <button type="button" onClick={() => select(item.id)}>{names.get(item.from_node_id)} → {names.get(item.to_node_id)} · {item.relation}</button>
      <span>{item.source} · {(item.confidence * 100).toFixed(1)}% · 距上次观察 {age(item.freshness_seconds)}</span>
    </li>)}</ul>{!graph.edges.length && <p>暂无关系</p>}</Card>
  </div>;
}

